import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Learning Universal Policies via Text-Guided Video Generation","description":"","frontmatter":{"title":"Learning Universal Policies via Text-Guided Video Generation","arxiv":"2302.00111","date":"2023-01-31","authors":"Yilun Du, Mengjiao Yang, Bo Dai, Hanjun Dai, Ofir Nachum, Joshua B. Tenenbaum, Dale Schuurmans, Pieter Abbeel","categories":"cs.AI","topics":"视频即策略, 通用智能体, 扩散规划","outline":[2,2]},"headers":[],"relativePath":"papers/2302.00111.md","filePath":"papers/2302.00111.md","lastUpdated":null}'),e={name:"papers/2302.00111.md"};function l(m,s,i,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="learning-universal-policies-via-text-guided-video-generation" tabindex="-1">Learning Universal Policies via Text-Guided Video Generation <a class="header-anchor" href="#learning-universal-policies-via-text-guided-video-generation" aria-label="Permalink to &quot;Learning Universal Policies via Text-Guided Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2302.00111" target="_blank" rel="noreferrer">2302.00111</a></td></tr><tr><td><strong>提交日期</strong></td><td>2023-01-31</td></tr><tr><td><strong>作者</strong></td><td>Yilun Du, Mengjiao Yang, Bo Dai, Hanjun Dai, Ofir Nachum, Joshua B. Tenenbaum, Dale Schuurmans, Pieter Abbeel</td></tr><tr><td><strong>分类</strong></td><td>cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>把序贯决策改写成「文本条件视频生成 + 逆动力学解码」，用图像当跨环境的通用状态接口、用文本代替奖励函数，从而让互联网视频预训练的知识直接迁移进机器人策略。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>论文瞄准的是通用智能体的两个结构性障碍。第一是<strong>接口不统一</strong>：MuJoCo 的关节空间与 Atari 的像素-离散动作根本不是同一种东西，任何想跨环境共享知识的方法都得先造一个复杂的统一状态表示，而 Gato 一类的 token 化方案又切断了与预训练视觉语言模型的联系。第二是<strong>奖励难以指定与迁移</strong>：MDP 要求一个实值奖励函数，可现实里怎么为&quot;把红块放在青块右边&quot;写奖励并不清楚，而且换个环境就得重写。作者的主张是：视频天然是跨环境通用的观测-行为载体，文本天然是跨环境通用的任务说明，于是可以绕开状态设计与奖励设计两件事。这件事之所以重要，是因为它把互联网上海量的、没有动作标签、没有奖励标签的视频，变成了可以直接为控制服务的&quot;示范&quot;。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>三条线各有断点。<strong>世界模型</strong>（Dreamer、Trajectory Transformer 一系）把动力学学习与规划分开，但训练数据必须是严格的 state-action-reward 三元组，这与 YouTube 视频不兼容；VPT 用逆动力学给无标注视频打伪标签解决了数据格式问题，但逆动力学本身不支持基于模型的规划，只能做模仿。<strong>扩散决策</strong>（Diffuser、Decision Diffuser）已经把扩散用于轨迹生成，但扩散的对象是关节空间的状态-动作序列，因而是任务专用、从零训练的，拿不到互联网知识。<strong>通用智能体</strong>（Gato、Multi-Game DT）要么只能在状态动作空间相同的环境族内运作，要么依赖人工设计的 tokenization。<strong>语言条件策略</strong>（BC-Z、CLIPort 一系）直接在某个具体机器人的动作空间里训练策略，跨形态、跨环境的泛化因此仍未解决。作者据此声称，本文是第一个把图像当作通用状态与动作空间、以打通环境间乃至人-机器人之间知识迁移的工作。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是一个已被文生图验证的经验事实：大规模文本条件生成模型表现出组合泛化——它能画出训练里没有的概念组合。既然语言的组合性可以驱动图像的组合性，那么如果把&quot;要执行的行为&quot;也编码成图像序列，语言的组合性就能直接驱动行为的组合性。顺着这条线追问下去会碰到三个具体障碍。其一，文生视频模型默认生成不受约束的视频，而规划必须从当前观测出发；作者先试了 Diffuser 式的推理期约束（采样时把第一帧钉死），发现后续帧会显著偏离观测，于是改成训练期显式条件。其二，普通文生视频里环境状态会随时间大幅漂移，可规划要求场景保持一致；既然要在每一帧都强调&quot;这是同一个场景&quot;，那就把观测帧在时间轴上平铺、逐帧拼进去噪输入——这正好可以复用时序超分模型的架构。其三，长时程直接生成会因搜索空间爆炸而失败，而经典规划的解法是先粗后细；视频恰好有天然的时间层次，粗层是稀疏采样的关键帧，细层由时序超分补齐。三个障碍的解法拼起来就是 UniPi。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>让&quot;策略&quot;输出图像而不是关节角，环境之间的差异就从状态空间的差异降级成了外观的差异，而外观差异恰是预训练视觉模型最擅长吸收的东西。视频计划是人可读的，可以被检查、被引导、被分层细化；剩下的&quot;这一帧到下一帧该发什么指令&quot;是一个局部的、机器人专属的小问题，交给一个小逆动力学模型即可。前人方法失效是因为它们把通用性押在动作空间上，而动作空间恰恰是最不通用的那一层。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以组合环境里的一条指令&quot;把红块放到青块右边&quot;为例：</p><ul><li><strong>观测与指令</strong>：拍下当前桌面图像 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，用 T5-XXL（4.6B）编码文本 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span>。</li><li><strong>粗层规划</strong>：一个 1.7B 的首帧条件视频扩散模型生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">10</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">48</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span> 的稀疏视频（每 8 帧取一帧），画面里机器人先抓白块、放进颜料碗上色、再摆到目标位置。首帧条件的实现是把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 复制到所有帧索引上作为条件。</li><li><strong>一致性</strong>：去噪时把观测帧沿时间平铺后与噪声帧逐通道拼接，强行压住场景漂移；时间维用时序卷积而非时序注意力以保持局部时间一致性。</li><li><strong>细化</strong>：另一个 1.7B 的时序超分模型把视频补到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">20</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">48</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">64</span></span></span></span>（每 4 帧取一帧）。</li><li><strong>解码动作</strong>：一个很小的逆动力学模型（一层 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">3</span></span></span></span> 卷积 + 3 层残差卷积 + 全局池化 + <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">128</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">7</span><span class="mclose">)</span></span></span></span> 的 MLP）从相邻帧回归 7 维控制量；它与规划器完全独立训练，可以用更小、更次优的数据。</li><li><strong>执行</strong>：论文出于计算效率<strong>全部采用开环执行</strong>，即一次生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 帧、解出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 个动作后顺序执行，而不是每步重规划的 MPC。</li><li><strong>可选引导</strong>：推理期可以叠加一个先验 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span>（学好的图像分类器，或指向某张目标图的 Dirac），把计划往特定状态偏。</li></ul><p>采样时用 classifier-free guidance：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">s</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1944em;"><span class="mord">^</span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mclose">)</span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">c</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">ω</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">s</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1132em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mclose">)</span></span></span></span>。训练规模是 2M 步、batch 2048、学习率 1e-4、256 块 TPU-v4。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的形式化贡献是提出 <strong>UPDP（Unified Predictive Decision Process）</strong> 来替代 MDP。一个 UPDP 是四元组</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7805em;vertical-align:-0.0972em;"></span><span class="mord mathcal" style="margin-right:0.0593em;">G</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">⟨</span><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ρ</span><span class="mclose">⟩</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ρ</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1413em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mopen">(</span><span class="mord"><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.1464em;">X</span></span></span></span> 是图像观测空间，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span></span></span></span> 是文本任务描述空间，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 是有限时域，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 是一个条件视频生成器，输出 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 步图像序列上的分布。与 MDP 的三点差别值得逐条看清楚：MDP 需要 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0019em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">s</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">a</span><span class="mclose">)</span></span></span></span>，它同时依赖环境与智能体的动作空间；UPDP 里根本没有动作，动力学被吸收进 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>，因此 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 与具体机器人无关。MDP 需要实值奖励；UPDP 用 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 指定任务，奖励设计问题消失。MDP 是马尔可夫的；UPDP 直接对整段轨迹建模，因此允许非马尔可夫的图像状态。</p><p>动作则由一个<strong>轨迹-任务条件策略</strong>补回来：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="mopen">(</span><span class="mord">⋅</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1413em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose"><span class="mclose">}</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-2.453em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">h</span><span class="mrel mtight">=</span><span class="mord mtight">0</span></span></span></span><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">:</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9747em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.1464em;">X</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">→</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.1413em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mopen">(</span><span class="mord"><span class="mord mathcal">A</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8913em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0813em;">H</span></span></span></span></span></span></span></span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span></span></p><p>它在给定完整图像轨迹后输出动作序列，本文用逆动力学实例化。这个分解的意义是：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span> 承担全部&quot;想做什么&quot;，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span> 只承担&quot;怎么发指令&quot;，前者可跨环境复用，后者按机器人各自训练。作者也坦白代价——UPDP 需要视频与文本数据，而 MDP 不需要，所以哪种抽象更合适取决于手头有什么数据。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：语言的组合性能否转成行为的组合性？</strong> 在积木上色-摆位的组合环境里，指令按 70/30 分成训练见过与未见过两组，视频模型在 20 万条脚本生成的视频上训练。表 1 里 UniPi 在见过/未见过 × Place/Relation 四格上分别是 59.1 / 53.2 / 60.1 / 46.1，而 State+Transformer BC、Image+Transformer BC、Image+TT、Diffuser 四个基线全部落在 3.7–19.4 区间。差距大到需要解释，见 §11。</p><p><strong>问题二：多任务与跨环境迁移？</strong> 在 CLIPort 的语言引导操作套件上训练、在另外三个环境上测试，UniPi 拿到 51.6 / 75.5 / 45.7，基线最好只有 21.7。这里有一处需要注明：正文写&quot;10 个训练任务&quot;，但附录 A.5 列出的训练环境实际是 11 个；而且三个&quot;测试任务&quot;分别是训练任务的颜色划分变体（如训练 <code>put-block-in-bowl-unseen-colors</code>、测试 <code>put-block-in-bowl-seen-colors</code>），因此&quot;迁移到新环境&quot;的强度低于字面读感。</p><p><strong>问题三：互联网预训练值多少？</strong> 在 1400 万视频-文本对 + 6000 万图文对 + LAION-400M 上预训练后，在 Bridge 数据的 7.2k 视频-文本对（<strong>文本用的是 task ID 而非自由语言</strong>）上微调。表 4 显示预训练把 FID 从 17.75 降到 14.54、FVD 从 288.02 降到 264.66，CLIP 分只从 24.43 微升到 24.54（作者自己说 marginally）。这里正文有一处措辞错误：写成&quot;achieves significantly higher FID and FVD&quot;，而 FID/FVD 是越低越好，表头箭头也是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mrel">↓</span></span></span></span>，应为更低。成功率一项从 72.6% 升到 77.1%，但这个&quot;成功率&quot;是<strong>用一个分类器看生成视频的最后一帧判定的</strong>，不是真机执行结果——论文自己也说这是因为缺乏面向控制的生成指标而设计的 surrogate。</p><p><strong>消融</strong>（表 2，在见过的指令上测）：首帧条件是决定性的（13.2→52.4 / 12.4→34.7）；帧平铺一致性在 Place 上只加 0.8（52.4→53.2，而该列标准差是 ±2.9/±3.0，落在噪声内），在 Relation 上加 4.7；时序层次加 5.9 / 13.8。所以&quot;每个组件都关键&quot;的说法对帧一致性在 Place 一列上并不成立。</p><p>作者在 Limitations 里承认两点：扩散很慢（生成一段高保真视频要一分钟，初步实验里蒸馏可提速约 16 倍），以及所有实验环境基本是全可观测的，部分可观测下视频模型可能幻觉出不存在的物体。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：通用智能体卡在状态空间不统一与奖励难以指定这两件事上。UniPi 用图像当通用状态接口、文本当任务说明，把决策改写成首帧与文本条件的视频生成，再用一个小逆动力学模型把视频解码成动作。为了让生成的视频可执行，它需要三个技术改动：训练期显式首帧条件、观测帧沿时间平铺以压住场景漂移、先粗后细的时序层次生成。这套框架被形式化成 UPDP 抽象，其核心是把与机器人无关的&quot;想做什么&quot;和机器人专属的&quot;怎么动&quot;彻底分开。互联网视频预训练能显著改善生成质量与基于分类器的成功代理指标，说明非机器人数据确实能迁移。</p><p><strong>3 句话版</strong>：把策略表示成视频，环境差异就降级成外观差异，于是预训练视觉知识可以直接迁移。视频计划由首帧条件扩散生成，动作由独立训练的逆动力学解出。在组合泛化与多任务迁移上大幅超过直接回归动作的基线。</p><p><strong>1 句话版</strong>：视频即策略——用文生视频当规划器，把动作解码降级成一个小的局部问题。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要害的一条是：<strong>逆动力学能从生成的视频里可靠地读出动作，且生成视频的误差不会在开环执行中累积</strong>。整套框架的说服力建立在&quot;规划与控制可以彻底解耦&quot;上，而这个解耦成立的前提是视频帧包含了足够且正确的动作信息。论文的执行方式把这个假设推到极限——出于计算效率，全部实验用<strong>开环</strong>控制，一次生成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 帧后顺序执行完；只要视频里有一处物理上不可实现的跳变，后续所有动作都建立在错误的世界状态上，而没有任何反馈机制可以纠正。论文为这一假设提供的证据是间接的：图 4 展示&quot;合成的视频计划与实际执行大致对齐&quot;，仿真环境里对不可行动作设了 2 秒超时，仅此而已；全文没有测量&quot;生成帧对 vs 真实帧对&quot;下逆动力学动作误差的差距，也没有开环与闭环 MPC 的对照实验。这个假设在真实世界一节最脆弱：那里根本没有真机执行，成功率由一个看末帧的分类器给出，因此&quot;视频计划可执行&quot;这一步在真实机器人上从未被验证过。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不必复现 1.7B 的视频扩散。取一个已有的小规模首帧条件视频预测模型（在 <a href="/notes/papers/2308.12952">BridgeData V2</a> 的子集上训练即可）与一个按论文规格搭的小逆动力学模型，做<strong>逆动力学的分布偏移测量</strong>：在留出集上分别用（a）真实相邻帧对、（b）模型生成的相邻帧对，喂给同一个逆动力学模型，比较预测动作与真值动作的 MSE 与逐维相关性。再把两组动作分别在仿真里开环回放，记录 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 步后末端位姿的偏差随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 的增长曲线。判据：若 (b) 的动作误差与 (a) 相当、且位姿偏差随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 亚线性增长，支持论文的解耦假设；若 (b) 的误差显著更大且偏差随 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span> 超线性增长，说明开环执行是 §9 指出的真实瓶颈，UniPi 的仿真成绩依赖于任务时域足够短。这个实验一周内可完成，且完全不需要重训生成器。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>对表 1 与表 3 里 3–5 倍的巨大差距，最有力的替代解释是<strong>监督量不对等</strong>，而不是&quot;视频即策略&quot;这个 framing 本身更好。UniPi 的视频模型在 20 万条脚本视频上训练，逆动力学额外用了 2 万（组合任务）到 20 万（CLIPort 任务）条带动作标注的视频，而 Transformer BC / TT / Diffuser 只从动作标注里学习。更关键的是这些任务的示范全部由脚本 oracle 生成，因而是高度规整、几乎无多模态的——视频模型在这种数据上等价于学了一个近乎确定性的&quot;脚本回放器&quot;，而 BC 基线要在关节空间里拟合同一条脚本却拿不到中间视觉状态作为脚手架。检验方式是加一行对照：给 BC/TT 基线同样的&quot;中间目标图像&quot;作为额外输入（即把 UniPi 生成的视频计划直接喂给它们，或用真值中间帧作为 oracle 上界），若基线成功率跳到 UniPi 量级，那么增益归于&quot;有了稠密的视觉子目标&quot;而非&quot;用生成模型规划&quot;。第二个攻击点在 §4.2：三个&quot;未见测试任务&quot;其实是训练任务的颜色划分变体，且训练集里已含同名任务的另一颜色划分，这不足以支撑&quot;泛化到新环境&quot;的表述；干净的做法是留出一整类任务（例如全部 tower-of-hanoi）再测。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>UniPi 把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">ρ</span></span></span></span>（生成什么）与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">π</span></span></span></span>（怎么动）分成两个独立训练、单向串联的模块，动作信息只能从视频里被动读出。这带来一个结构性代价：生成器完全不知道自己画出的运动是否可执行，而逆动力学也无法把&quot;这段做不到&quot;的信号回传。一个非增量的重构是把它们改成<strong>同一个联合模型的两种读出</strong>——训练一个以图像序列为主干、以动作为辅助输出的模型，让动作可解码性成为生成过程的一个约束而不是下游任务。可借鉴的相邻领域工具是可控生成里的能量引导：把逆动力学的残差 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.0361em;vertical-align:-0.2861em;"></span><span class="mord">∥</span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord text mtight"><span class="mord mtight">pred</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">ID</span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">h</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">h</span><span class="mbin mtight">+</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord">∥</span></span></span></span> 当作一个能量项，在采样时对视频轨迹做引导，使得只有&quot;逆动力学读得出、且读出的动作在关节限位内&quot;的帧对才被采纳。这正好复用 UniPi 已有的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">h</span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span><span class="mclose">)</span></span></span></span> 先验接口。第一个实验很小：在组合环境里固定训练好的生成器与逆动力学，仅在推理期加入这一项能量引导，比较加与不加时的任务完成率与&quot;物理不可行动作被超时截断&quot;的比例。若不可行动作比例显著下降而完成率上升，就说明&quot;可执行性&quot;应当被当作生成时的一等约束，而不是执行时才发现的问题——这个 framing 也顺带给 <a href="/notes/papers/2310.08576">AVDC</a> 那类完全不用动作标签的方法提供了一条不需要重新标注数据的加固路径。</p>',40)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
